const express = require('express');
const execa = require('execa');
const { Contract } = require('../models/contract');

const app = express();

app.get('/api/procurement/contracts/:contractId/extract-clauses', async (req, res) => {
  if (!req.user || !req.user.organizationId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Validate that user's organization is either the buyer or supplier party
  const contract = await Contract.findOne({
    where: {
      id: req.params.contractId,
      $or: [
        { buyerOrgId: req.user.organizationId },
        { supplierOrgId: req.user.organizationId }
      ]
    }
  });

  if (!contract) {
    return res.status(404).json({ error: 'Contract not found or access unauthorized' });
  }

  try {
    const { stdout } = await execa('node', [
      './jobs/generate-contract-summary.js',
      req.params.contractId
    ]);

    res.setHeader('Content-Type', 'application/json');
    res.send(stdout);
  } catch (err) {
    res.status(500).json({ error: 'Contract clause extraction worker failed' });
  }
});

app.listen(8082);
